s = input().strip()

# Must have exactly one dot
if s.count('.') != 1:
    print("No")
else:
    name, ext = s.split('.', 1)

    # Nonempty name and extension
    if not name or not ext:
        print("No")
    else:
        # Name must start with a letter
        if not name[0].isalpha():
            print("No")
        else:
            # At most 3 digits in the whole filename (excluding the dot)
            digits = sum(c.isdigit() for c in name + ext)
            if digits > 3:
                print("No")
            else:
                # Extension must be one of the allowed types
                if ext in {"txt", "exe", "dll"}:
                    print("Yes")
                else:
                    print("No")

