if n <= 1:
    print(False)
else:
    n_sqrt = 0
    while n_sqrt * n_sqrt < n:
        n_sqrt += 1
    limit = min(n_sqrt + 1, n - 1)
    is_prime = True
    for i in range(2, limit + 1):
        if n % i == 0:
